<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
  <title>@yield('title', 'DecodeMyBrain')</title>
  <link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap" rel="stylesheet">
  <style>
    :root{--ink:#171513;--muted:#6d6257;--line:#eadbc4;--cream:#fffaf2;--yellow:#ffd84f;--orange:#ef6a30;--green:#36a664}*{box-sizing:border-box}body{margin:0;background:#fff;color:var(--ink);font-family:'DM Sans',sans-serif}.shell{width:100%;min-height:100vh;background:#fff}.nav{height:78px;display:flex;align-items:center;justify-content:space-between;padding:0 clamp(24px,5vw,84px);border-bottom:1px solid #f0e4d2;background:#fff}.brand{display:inline-flex;align-items:center;gap:10px;color:var(--ink);font-size:21px;font-weight:700;text-decoration:none}.brand-mark{display:grid;place-items:center;width:38px;height:38px;border:1px solid #e6bb2c;border-radius:11px;background:var(--yellow);font-family:Georgia;font-size:21px}.nav-links{display:flex;align-items:center;gap:28px}.nav-links a{color:var(--ink);text-decoration:none;font-size:15px}.nav-links a:hover,.text-link{color:var(--orange)!important}.button{display:inline-flex;justify-content:center;align-items:center;min-height:52px;padding:12px 24px;border:1px solid #e5b92e;border-radius:12px;background:var(--yellow);color:var(--ink);font:600 16px 'DM Sans';text-decoration:none;cursor:pointer;box-shadow:0 10px 20px rgba(255,216,79,.2)}.button.secondary{background:#fff;border-color:var(--line);box-shadow:none}.button.dark{background:#171513;color:#fff;border-color:#171513}.button:disabled{opacity:.55;cursor:not-allowed}.page{padding:62px clamp(24px,5vw,84px)}.display{font:600 clamp(34px,5vw,56px)/1.08 'Playfair Display',serif;letter-spacing:-1.5px}.heading{font:600 clamp(34px,4vw,44px)/1.1 'Playfair Display',serif}.lead{color:#3d3731;font-size:18px;line-height:1.55}.eyebrow{display:inline-block;background:#fff0b8;border-radius:999px;padding:7px 16px;font-size:14px}.alert{margin:0 auto 20px;max-width:640px;padding:13px 16px;border-radius:10px;background:#fff3e6;color:#a44215;border:1px solid #ffd3b8}.alert.success{background:#eaf8ef;color:#197442;border-color:#b9e7c8}.footer{display:flex;justify-content:space-between;gap:20px;border-top:1px solid var(--line);padding:28px clamp(24px,5vw,84px);color:var(--muted);font-size:14px}.footer a{color:var(--ink);text-decoration:none;margin-left:22px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.field{display:flex;flex-direction:column;gap:8px}.field.full{grid-column:1/-1}.field label{font-weight:600;font-size:15px}.field input,.field textarea,.field select{width:100%;border:1px solid var(--line);border-radius:12px;padding:14px 16px;background:#fff;color:var(--ink);font:16px 'DM Sans'}.field input.is-invalid{border-color:#c94d21;background:#fff8f4}.field-error{margin:0;color:#a44215;font-size:13px;line-height:1.35}.field textarea{min-height:92px;resize:vertical}.help{color:var(--muted);font-size:14px}.hidden{display:none!important}@media(max-width:800px){.nav{height:auto;padding:18px 22px;align-items:flex-start}.nav-links{display:none}.page{padding:45px 22px}.footer{padding:24px 22px;flex-direction:column}.form-grid{grid-template-columns:1fr}.field.full{grid-column:auto}}
  </style>
  @stack('styles')
</head>
<body><div class="shell">@if(trim($__env->yieldContent('show_public_nav')) === 'yes')@include('public.partials.nav')@endif @yield('body')</div><script>
document.querySelectorAll('input[name="dob"]').forEach(function (input) { if(input.type==='date'){input.type='text'}input.placeholder='DD/MM/YYYY';input.inputMode='numeric';input.autocomplete='bday';input.pattern='[0-9]{2}/[0-9]{2}/[0-9]{4}';input.title='Enter the date as DD/MM/YYYY';input.addEventListener('input',function(){var digits=input.value.replace(/\D/g,'').slice(0,8);input.value=digits.replace(/^(\d{2})(\d)/,'$1/$2').replace(/^(\d{2}\/\d{2})(\d)/,'$1/$2')})});
</script>@stack('scripts')</body>
</html>
